import java.util.Scanner;

public class Main {
    static final int LIMIT = 1000005;
    static final int MODULO = 1000000007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p_num = sc.nextInt();
        int k_num = sc.nextInt();

        if (k_num == 0) {
            long res = 1;
            for (int i = 1; i < p_num; ++i) {
                res = (res * p_num) % MODULO;
            }
            System.out.println(res);
            sc.close();
            return;
        }

        int[] perm = new int[p_num];
        boolean[] visited_nodes = new boolean[p_num];

        for (int i = 1; i < p_num; ++i) {
            perm[i] = (int)((long)k_num * i % p_num);
        }

        long total_ans = 1;

        for (int start_point = 0; start_point < p_num; ++start_point) {
            if (!visited_nodes[start_point]) {
                int cycle_size = 0;
                int current_index = start_point;
                int product_modulo = 1;

                while (!visited_nodes[current_index]) {
                    visited_nodes[current_index] = true;
                    current_index = perm[current_index];
                    cycle_size++;
                    product_modulo = (int)((long)product_modulo * k_num % p_num);
                }

                if (cycle_size == 1) {
                    int factor = (k_num == 1) ? p_num : 1;
                    total_ans = (total_ans * factor) % MODULO;
                } else {
                    // Asserts are not used in Java; assuming correctness
                    // assert(product_modulo == 1);
                    total_ans = (total_ans * p_num) % MODULO;
                }
            }
        }

        System.out.println(total_ans);
        sc.close();
    }
}

